const accountTag = 'replace-with-cloudflare-account-id';
if (accountTag === 'replace-with-cloudflare-account-id') {
  throw new Error('Set the Cloudflare account ID in this node before activating the workflow.');
}

const end = new Date();
const start = new Date(end.getTime() - 7 * 24 * 60 * 60 * 1000);
const startIso = start.toISOString();
const endIso = end.toISOString();

const query = `query WeeklyRum($accountTag: string!, $start: Time!, $end: Time!) {
  viewer {
    accounts(filter: { accountTag: $accountTag }) {
      kheTotal: rumPageloadEventsAdaptiveGroups(limit: 1, filter: { datetime_geq: $start, datetime_leq: $end, requestHost: "khe.ee", bot: 0 }) {
        count
        sum { visits }
      }
      kheTopPages: rumPageloadEventsAdaptiveGroups(limit: 8, orderBy: [count_DESC], filter: { datetime_geq: $start, datetime_leq: $end, requestHost: "khe.ee", bot: 0 }) {
        count
        sum { visits }
        dimensions { requestPath }
      }
      gamesTotal: rumPageloadEventsAdaptiveGroups(limit: 1, filter: { datetime_geq: $start, datetime_leq: $end, requestHost: "games.khe.ee", bot: 0 }) {
        count
        sum { visits }
      }
      gamesTopPages: rumPageloadEventsAdaptiveGroups(limit: 8, orderBy: [count_DESC], filter: { datetime_geq: $start, datetime_leq: $end, requestHost: "games.khe.ee", bot: 0 }) {
        count
        sum { visits }
        dimensions { requestPath }
      }
    }
  }
}`;

return [{
  json: {
    generatedAt: endIso,
    period: {
      start: startIso,
      end: endIso,
      days: 7
    },
    request: {
      query,
      variables: {
        accountTag,
        start: startIso,
        end: endIso
      }
    }
  }
}];

// Files from scripts/os-status.sh on the Proxmox host and the Docker VM. A
// missing, unreadable or stale file is reported as null, never as an error,
// so the analytics part of the report still runs; read failures are listed
// in errors so a broken read does not pass for a missing file.
const maxAgeMs = 48 * 60 * 60 * 1000;
const status = { host: null, vm: null, errors: [] };
const items = $input.all();

async function readText(i) {
  try {
    return (await this.helpers.getBinaryDataBuffer(i, 'data')).toString('utf8');
  } catch (error) {
    const inline = items[i].binary.data.data;
    if (typeof inline === 'string' && !inline.startsWith('filesystem')) {
      return Buffer.from(inline, 'base64').toString('utf8');
    }
    throw error;
  }
}

for (let i = 0; i < items.length; i++) {
  if (!items[i].binary?.data) {
    if (items[i].json?.error) status.errors.push(String(items[i].json.error));
    continue;
  }
  const fileName = items[i].binary.data.fileName ?? `file ${i}`;
  let parsed;
  try {
    parsed = JSON.parse(await readText.call(this, i));
  } catch (error) {
    status.errors.push(`${fileName}: ${error.message}`);
    continue;
  }
  const key = parsed.role === 'pve-host' ? 'host' : parsed.role === 'vm' ? 'vm' : null;
  if (!key) continue;
  const ageMs = Date.now() - Date.parse(parsed.generatedAt);
  if (!(ageMs < maxAgeMs)) continue;
  status[key] = {
    generatedAt: parsed.generatedAt,
    os: parsed.os,
    pveVersion: parsed.pveVersion,
    runningKernel: parsed.runningKernel,
    newestKernel: parsed.newestKernel,
    rebootRequired: parsed.rebootRequired === true,
    pendingUpdates: Number(parsed.pendingUpdates ?? 0)
  };
}

return [{ json: status }];

const source = $('Fetch Cloudflare Analytics').first().json;
if (source.errors?.length) {
  throw new Error(`Cloudflare GraphQL error: ${JSON.stringify(source.errors)}`);
}

const account = source.data?.viewer?.accounts?.[0] ?? {};
const meta = $('Build Cloudflare Query').first().json;

function totals(rows) {
  const row = Array.isArray(rows) ? rows[0] : undefined;
  return {
    pageViews: Number(row?.count ?? 0),
    visits: Number(row?.sum?.visits ?? 0)
  };
}

function topPages(rows) {
  return (Array.isArray(rows) ? rows : [])
    .map((row) => ({
      path: row?.dimensions?.requestPath || '/',
      pageViews: Number(row?.count ?? 0),
      visits: Number(row?.sum?.visits ?? 0)
    }))
    .filter((row) => row.pageViews > 0);
}

return [{
  json: {
    generatedAt: meta.generatedAt,
    period: meta.period,
    sites: [
      {
        host: 'khe.ee',
        ...totals(account.kheTotal),
        topPages: topPages(account.kheTopPages)
      },
      {
        host: 'games.khe.ee',
        ...totals(account.gamesTotal),
        topPages: topPages(account.gamesTopPages)
      }
    ],
    osUpdates: $('Parse OS Status').first().json,
    uptimeSummary: {
      source: 'manual',
      publicServicesHealthy: null
    },
    visibility: 'internal',
    notes: [
      'Internal operational report. Do not publish this raw file.',
      'Public portfolio metrics are written separately from an allowlist.'
    ]
  }
}];

const source = $('Fetch Cloudflare Analytics').first().json;
if (source.errors?.length) {
  throw new Error(`Cloudflare GraphQL error: ${JSON.stringify(source.errors)}`);
}

const account = source.data?.viewer?.accounts?.[0] ?? {};
const meta = $('Build Cloudflare Query').first().json;

function totals(rows) {
  const row = Array.isArray(rows) ? rows[0] : undefined;
  return {
    pageViews: Number(row?.count ?? 0),
    visits: Number(row?.sum?.visits ?? 0)
  };
}

return [{
  json: {
    generatedAt: meta.generatedAt,
    periodDays: meta.period.days,
    sites: [
      {
        host: 'khe.ee',
        ...totals(account.kheTotal)
      },
      {
        host: 'games.khe.ee',
        ...totals(account.gamesTotal)
      }
    ],
    source: 'Cloudflare Web Analytics + n8n'
  }
}];

const report = $input.first().json;
const os = $('Parse OS Status').first().json;

function osLine(label, status) {
  if (!status) return `${label}: not reported`;
  const parts = [];
  if (status.pendingUpdates > 0) parts.push(`${status.pendingUpdates} updates`);
  if (status.rebootRequired) {
    parts.push(status.newestKernel && status.newestKernel !== status.runningKernel
      ? `reboot due (${status.runningKernel} -> ${status.newestKernel})`
      : 'reboot due');
  }
  return `${label}: ${parts.length ? parts.join(', ') : 'up to date'}`;
}
const generatedAt = new Date(report.generatedAt).toLocaleString('et-EE', {
  timeZone: 'Europe/Tallinn',
  dateStyle: 'medium',
  timeStyle: 'short'
});

const lines = [
  'Weekly homelab report',
  `Generated: ${generatedAt}`,
  `Period: last ${report.periodDays} days`,
  '',
  ...report.sites.map((site) => `${site.host}: ${site.visits} visits, ${site.pageViews} page views`),
  '',
  osLine('Proxmox', os.host),
  osLine('Docker VM', os.vm),
  ...(os.errors?.length ? [`OS status: ${os.errors.length} file(s) unreadable, see the internal report`] : []),
  '',
  'Public metrics: https://khe.ee/reports/portfolio-metrics.json'
];

return [{
  json: {
    text: lines.join('\n')
  }
}];
